function parseFieldSignal(raw: string | bigint | undefined, name: string): bigint {
  if (raw === undefined) {
    throw new RangeError(`Missing public signal "${name}"`);
  }
  if (typeof raw === "string" && !/^(0|[1-9][0-9]*)$/.test(raw)) {
    throw new RangeError(`Public signal "${name}" must be a non-negative decimal integer`);
  }
  const value = typeof raw === "bigint" ? raw : BigInt(raw);
  if (value < 0n || value >= SNARK_SCALAR_FIELD) {
    throw new RangeError(`Public signal "${name}" is outside bn128 scalar field`);
  }
  return value;
}

function formatFieldSignal(value: bigint, name: string): string {
  if (typeof value !== "bigint" || value < 0n || value >= SNARK_SCALAR_FIELD) {
    throw new RangeError(`Public signal "${name}" is outside bn128 scalar field`);
  }
  return value.toString(10);
}

export function toPublicSignalsArray(signals: ReserveRailPublicSignals): string[] {
  return [
    formatFieldSignal(signals.policyRoot, "policyRoot"),
    formatFieldSignal(signals.prevCommitment, "prevCommitment"),
    formatFieldSignal(signals.newCommitment, "newCommitment"),
    formatFieldSignal(signals.recipient, "recipient"),
    formatFieldSignal(signals.amount, "amount"),
    formatFieldSignal(signals.epoch, "epoch"),
    formatFieldSignal(signals.invoiceHash, "invoiceHash"),
  ];
}

export function fromPublicSignalsArray(
  rawSignals: readonly (string | bigint)[],
): ReserveRailPublicSignals {
  if (rawSignals.length !== 7) {
    throw new RangeError(
      `Expected publicSignals length 7, received ${rawSignals.length}`,
    );
  }
  return {
    policyRoot: parseFieldSignal(rawSignals[0], "policyRoot"),
    prevCommitment: parseFieldSignal(rawSignals[1], "prevCommitment"),
    newCommitment: parseFieldSignal(rawSignals[2], "newCommitment"),
    recipient: parseFieldSignal(rawSignals[3], "recipient"),
    amount: parseFieldSignal(rawSignals[4], "amount"),
    epoch: parseFieldSignal(rawSignals[5], "epoch"),
    invoiceHash: parseFieldSignal(rawSignals[6], "invoiceHash"),
  };
}
